export function parsePrimeUiExportManifest(
  value: unknown,
): PrimeUiExportManifest {
  if (!value || typeof value !== "object") {
    throw new Error("Export manifest is invalid.");
  }

  const maybe = value as Record<string, unknown>;
  if (!maybe.export || typeof maybe.export !== "object") {
    throw new Error("Export manifest export payload is invalid.");
  }

  const parsed = primeUiExportManifestSchema.safeParse(value);
  if (!parsed.success) {
    const hasPageIssue = parsed.error.issues.some(
      (issue) => issue.path[0] === "pages",
    );

    throw new Error(
      hasPageIssue
        ? "Export manifest pages payload is invalid."
        : "Export manifest does not match expected schema.",
    );
  }

  return parsed.data;
}

export function parsePrimeUiComponentExportManifest(
  value: unknown,
): PrimeUiComponentExportManifest {
  if (!value || typeof value !== "object") {
    throw new Error("Component export manifest is invalid.");
  }

  const maybe = value as Record<string, unknown>;
  if (!maybe.component || typeof maybe.component !== "object") {
    throw new Error("Component export manifest component payload is invalid.");
  }

  const parsed = primeUiComponentExportManifestSchema.safeParse(value);
  if (!parsed.success) {
    throw new Error(
      `Component export manifest is invalid: ${parsed.error.issues
        .map((issue) => `${issue.path.join(".") || "<root>"} ${issue.message}`)
        .join("; ")}`,
    );
  }

  return parsed.data;
}
