import path from "node:path";
import { readFile } from "node:fs/promises";

import {
  parsePrimeUiComponentExportManifest,
  parsePrimeUiExportManifest,
} from "../lib/api-v1-contract.js";
import { ensureDir, extractZip, resetDir, writeUtf8 } from "../lib/fs.js";
import type { ProjectDataProvider } from "../sources/project-data-provider.js";
import type {
  PrimeUiToolContext,
  ProjectSyncSource,
} from "../sources/project-sync-source.js";
import { copyPageFromExport } from "./page-copy-service.js";
import { buildInspectPageReport } from "./page-inspect-report.js";
import type {
  PrimeUiComponentCandidatesInput,
  PrimeUiComponentCandidatesResult,
  PrimeUiComponentCatalogInput,
  PrimeUiComponentCatalogResult,
  PrimeUiComponentPreviewInput,
  PrimeUiComponentPreviewResult,
  PrimeUiComponentPropsValidateInput,
  PrimeUiComponentPropsValidateResult,
  PrimeUiCreateProjectApiPageInput,
  PrimeUiCreateProjectApiVariantInput,
  PrimeUiCopyComponentResult,
  PrimeUiCopyExportableResult,
  PrimeUiCopyPageResult,
  PrimeUiCopyRegistryComponentResult,
  PrimeUiCreateComponentExportResult,
  PrimeUiCreateExportResult,
  PrimeUiDownloadResult,
  PrimeUiExport,
  PrimeUiComponentExportManifest,
  PrimeUiIssueReportSubmitResult,
  PrimeUiExportManifest,
  PrimeUiInspectPageResult,
  PrimeUiProjectApiPagesResult,
  PrimeUiProjectApiVariantResult,
  PrimeUiProjectApiVariantSummaryResult,
  PrimeUiProjectApiVariantsResult,
  PrimeUiProjectDescriptionResult,
  PrimeUiProjectInfo,
  PrimeUiProjectPageDetailsResult,
  PrimeUiSubmitIssueReportInput,
} from "../types.js";
import { copyExportableFromExport } from "./exportable-copy-service.js";
import { copyComponentFromExport } from "./component-copy-service.js";
import { copyRegistryComponentFromExport } from "./registry-component-copy-service.js";
import {
  buildExportManifestArtifact,
  buildReferenceExportArtifact,
} from "./runtime-guidance.js";

type ProjectSyncServiceOptions = {
  projectRoot: string;
  targetProjectRoot: string;
  provider: ProjectDataProvider;
  pageDetailsBySlug?: Map<string, PrimeUiProjectPageDetailsResult>;
};

function buildManifestPath(exportsRoot: string, exportId: string): string {
  return path.join(exportsRoot, `${exportId}.manifest.json`);
}

function normalizeSlug(slug: string): string {
  const trimmed = slug.trim();
  if (!trimmed || trimmed === "/") {
    return "/";
  }

  const withLeadingSlash = trimmed.startsWith("/") ? trimmed : `/${trimmed}`;
  return withLeadingSlash.replace(/\/+$/, "") || "/";
}

export class ProjectSyncService implements ProjectSyncSource {
  private readonly provider: ProjectDataProvider;
  private readonly projectRoot: string;
  private readonly targetProjectRoot: string;
  private readonly primeUiRoot: string;
  private readonly tempRoot: string;
  private readonly exportsRoot: string;
  private readonly pageDetailsBySlug: Map<
    string,
    PrimeUiProjectPageDetailsResult
  >;

  constructor(options: ProjectSyncServiceOptions) {
    this.projectRoot = options.projectRoot;
    this.targetProjectRoot = options.targetProjectRoot;
    this.provider = options.provider;
    this.pageDetailsBySlug = options.pageDetailsBySlug ?? new Map();
    this.primeUiRoot = path.join(this.projectRoot, ".primeui");
    this.tempRoot = path.join(this.primeUiRoot, "temp");
    this.exportsRoot = path.join(this.tempRoot, "exports");
  }

  async getProjectInfo(
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiProjectInfo> {
    await this.ensureTempLayout();
    return this.provider.getProjectInfo();
  }

  async getProjectDescription(
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiProjectDescriptionResult> {
    return this.provider.getProjectDescription();
  }

  async upsertProjectDescription(
    projectDescription: string,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiProjectDescriptionResult> {
    return this.provider.upsertProjectDescription(projectDescription);
  }

  async listProjectPages(
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiProjectApiPagesResult> {
    return this.provider.listProjectPages();
  }

  async getProjectPage(
    pageId: string,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiProjectApiPagesResult> {
    return this.provider.getProjectPage(pageId);
  }

  async createProjectPage(
    input: PrimeUiCreateProjectApiPageInput,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiProjectApiPagesResult> {
    return this.provider.createProjectPage(input);
  }

  async listProjectPageVariants(
    pageId: string,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiProjectApiVariantsResult> {
    return this.provider.listProjectPageVariants(pageId);
  }

  async getProjectPageVariant(
    pageId: string,
    variantId: string,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiProjectApiVariantResult> {
    return this.provider.getProjectPageVariant(pageId, variantId);
  }

  async createProjectPageVariant(
    pageId: string,
    input: PrimeUiCreateProjectApiVariantInput,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiProjectApiVariantSummaryResult> {
    return this.provider.createProjectPageVariant(pageId, input);
  }

  async setProjectPageActiveVariant(
    pageId: string,
    variantId: string,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiProjectApiPagesResult> {
    return this.provider.setProjectPageActiveVariant(pageId, variantId);
  }

  async submitIssueReport(
    input: PrimeUiSubmitIssueReportInput,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiIssueReportSubmitResult> {
    return this.provider.submitIssueReport(input);
  }

  async getComponentCandidates(
    input: PrimeUiComponentCandidatesInput,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiComponentCandidatesResult> {
    return this.provider.getComponentCandidates(input);
  }

  async getComponentCatalog(
    input: PrimeUiComponentCatalogInput,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiComponentCatalogResult> {
    return this.provider.getComponentCatalog(input);
  }

  async getComponentPreview(
    input: PrimeUiComponentPreviewInput,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiComponentPreviewResult> {
    return this.provider.getComponentPreview(input);
  }

  async validateComponentProps(
    input: PrimeUiComponentPropsValidateInput,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiComponentPropsValidateResult> {
    return this.provider.validateComponentProps(input);
  }

  async listExports(_context?: PrimeUiToolContext): Promise<PrimeUiExport[]> {
    await this.ensureTempLayout();
    return this.provider.listExports();
  }

  async createExport(
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiCreateExportResult> {
    await this.ensureTempLayout();
    const result = await this.provider.createExport();
    const manifestPath = buildManifestPath(this.exportsRoot, result.export.id);
    await writeUtf8(manifestPath, `${JSON.stringify(result, null, 2)}\n`);

    return {
      ...result,
      guidance: {
        artifacts: [buildExportManifestArtifact(manifestPath)],
        requiredActions: `Call download_export with id "${result.export.id}" next before attempting any file transfer.`,
      },
    };
  }

  async createComponentExport(
    componentId: string,
    options: { propsValidationId?: string } = {},
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiCreateComponentExportResult> {
    await this.ensureTempLayout();
    const result = await this.provider.createComponentExport(componentId, {
      propsValidationId: options.propsValidationId,
    });
    const manifestPath = buildManifestPath(this.exportsRoot, result.export.id);
    await writeUtf8(manifestPath, `${JSON.stringify(result, null, 2)}\n`);

    return {
      ...result,
      guidance: {
        artifacts: [buildExportManifestArtifact(manifestPath)],
        requiredActions: `Call download_component_export with id "${result.export.id}" next. This is a component-track manifest; do not use page copy tools until a component registry copy tool is available.`,
      },
    };
  }

  async downloadExportById(
    id: string,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiDownloadResult> {
    await this.ensureTempLayout();

    const exportsList = await this.provider.listExports();
    const selected = exportsList.find((item) => item.id === id);

    if (!selected) {
      throw new Error(`Export not found: ${id}`);
    }

    const targetZipPath = path.join(this.exportsRoot, `${id}.zip`);
    const targetProjectPath = path.join(this.exportsRoot, id);
    const manifestPath = buildManifestPath(this.exportsRoot, id);

    let manifest: PrimeUiExportManifest;
    try {
      manifest = parsePrimeUiExportManifest(
        JSON.parse(await readFile(manifestPath, "utf-8")) as unknown,
      );
    } catch (error) {
      const reason = error instanceof Error ? error.message : String(error);
      throw new Error(
        `Export manifest is required for download id "${id}". Run create_export for this export before downloading. Details: ${reason}`,
      );
    }

    if (manifest.export.id !== id) {
      throw new Error(
        `Export manifest mismatch for id "${id}". Run create_export and retry download.`,
      );
    }

    await ensureDir(this.exportsRoot);
    await this.provider.downloadExportArchive(id, targetZipPath);

    await resetDir(targetProjectPath);
    await extractZip(targetZipPath, targetProjectPath);
    return {
      exportId: id,
      projectPath: targetProjectPath,
      manifestPath,
      guidance: {
        artifacts: [
          buildReferenceExportArtifact(targetProjectPath),
          buildExportManifestArtifact(manifestPath),
        ],
        requiredActions:
          "Use the export_manifest artifact as the source of truth for which files belong to the selected page, component, or exportable. Use the reference_export artifact as the golden example only when behavior diverges or integration is unclear. Then choose copy_page for full pages, copy_component for one selected block instance, or copy_exportable for shared exportables based on user intent.",
      },
    };
  }

  async downloadComponentExportById(
    id: string,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiDownloadResult> {
    await this.ensureTempLayout();

    const manifestPath = buildManifestPath(this.exportsRoot, id);
    const manifest = await this.readComponentExportManifest(id, manifestPath);
    const targetZipPath = path.join(this.exportsRoot, `${id}.zip`);
    const targetProjectPath = path.join(this.exportsRoot, id);

    await ensureDir(this.exportsRoot);
    await this.provider.downloadExportArchive(id, targetZipPath);

    await resetDir(targetProjectPath);
    await extractZip(targetZipPath, targetProjectPath);
    return {
      exportId: id,
      projectPath: targetProjectPath,
      manifestPath,
      guidance: {
        artifacts: [
          buildReferenceExportArtifact(targetProjectPath),
          buildExportManifestArtifact(manifestPath),
        ],
        requiredActions: `Use the component export_manifest artifact as the source of truth for component "${manifest.component.componentId}" and the reference_export artifact for inspection only. The next component-track step is a registry component copy tool; do not install the virtual page as a normal page.`,
      },
    };
  }

  async inspectPage(
    slug: string,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiInspectPageResult> {
    await this.ensureTempLayout();

    const pageDetails = await this.provider.getProjectPageBySlug(slug);
    const reportPayload = buildInspectPageReport(pageDetails);
    this.pageDetailsBySlug.set(normalizeSlug(slug), pageDetails);

    return {
      ...pageDetails,
      report: reportPayload.report,
      reportRows: reportPayload.reportRows,
    };
  }

  private async readComponentExportManifest(
    id: string,
    manifestPath: string,
  ): Promise<PrimeUiComponentExportManifest> {
    let manifest: PrimeUiComponentExportManifest;
    try {
      manifest = parsePrimeUiComponentExportManifest(
        JSON.parse(await readFile(manifestPath, "utf-8")) as unknown,
      );
    } catch (error) {
      const reason = error instanceof Error ? error.message : String(error);
      throw new Error(
        `Component export manifest is required for download id "${id}". Run create_component_export for this export before downloading. Details: ${reason}`,
      );
    }

    if (manifest.export.id !== id || manifest.exportId !== id) {
      throw new Error(
        `Component export manifest mismatch for id "${id}". Run create_component_export and retry download.`,
      );
    }

    return manifest;
  }

  async copyPage(
    originPageSlug: string,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiCopyPageResult> {
    await this.ensureTempLayout();

    return copyPageFromExport({
      projectRoot: this.targetProjectRoot,
      exportsRoot: this.exportsRoot,
      originPageSlug,
    });
  }

  async copyComponent(
    originPageSlug: string,
    blockId: string,
    componentId: string,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiCopyComponentResult> {
    await this.ensureTempLayout();

    const normalizedOriginSlug = normalizeSlug(originPageSlug);
    const cachedPageDetails = this.pageDetailsBySlug.get(normalizedOriginSlug);
    const pageDetails =
      cachedPageDetails ??
      (await this.provider.getProjectPageBySlug(originPageSlug));

    if (!cachedPageDetails) {
      this.pageDetailsBySlug.set(normalizedOriginSlug, pageDetails);
    }

    return copyComponentFromExport({
      projectRoot: this.targetProjectRoot,
      exportsRoot: this.exportsRoot,
      originPageSlug,
      blockId,
      componentId,
      pageDetails,
    });
  }

  async copyRegistryComponent(
    componentId: string,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiCopyRegistryComponentResult> {
    await this.ensureTempLayout();

    return copyRegistryComponentFromExport({
      projectRoot: this.targetProjectRoot,
      exportsRoot: this.exportsRoot,
      componentId,
    });
  }

  async copyExportable(
    exportableKey: string,
    _context?: PrimeUiToolContext,
  ): Promise<PrimeUiCopyExportableResult> {
    await this.ensureTempLayout();

    return copyExportableFromExport({
      projectRoot: this.targetProjectRoot,
      exportsRoot: this.exportsRoot,
      exportableKey,
    });
  }

  async clearTemp(_context?: PrimeUiToolContext): Promise<void> {
    await resetDir(this.tempRoot);
    await ensureDir(this.exportsRoot);
    this.pageDetailsBySlug.clear();
  }

  private async ensureTempLayout(): Promise<void> {
    await ensureDir(this.primeUiRoot);
    await ensureDir(this.tempRoot);
    await ensureDir(this.exportsRoot);
  }
}
