import { readFile } from "node:fs/promises";
import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";

import { COMPONENT_PICKER_RESOURCE_URI } from "./component-picker-contract.js";

const DEFAULT_FRAME_DOMAINS = ["https://app.primeui.com"];

function resolveFrameDomains(env: NodeJS.ProcessEnv): string[] {
  const configured = env.PRIMEUI_MCP_APP_FRAME_DOMAINS?.split(",")
    .map((value) => value.trim())
    .filter(Boolean);
  return configured?.length
    ? Array.from(new Set(configured))
    : DEFAULT_FRAME_DOMAINS;
}

export function registerComponentPickerResource(
  server: McpServer,
  options: { env?: NodeJS.ProcessEnv; html?: string } = {},
): void {
  const env = options.env ?? process.env;
  server.registerResource(
    "Prime component picker",
    COMPONENT_PICKER_RESOURCE_URI,
    { mimeType: "text/html;profile=mcp-app" },
    async () => ({
      contents: [
        {
          uri: COMPONENT_PICKER_RESOURCE_URI,
          mimeType: "text/html;profile=mcp-app",
          text:
            options.html ??
            (await readFile(
              new URL("./ui/component-picker.html", import.meta.url),
              "utf8",
            )),
          _meta: {
            ui: {
              prefersBorder: true,
              csp: {
                connectDomains: [],
                resourceDomains: [],
                frameDomains: resolveFrameDomains(env),
              },
            },
          },
        },
      ],
    }),
  );
}
